import importlib.util
import plato.models.nanochat
from plato.utils.third_party import ThirdPartyImportError, ensure_nanochat_importable

for name in ['opacus','kazoo','gymnasium','mlx','tiktoken','rustbpe','nanochat']:
 assert importlib.util.find_spec(name) is None, name
try:
 ensure_nanochat_importable()
except ThirdPartyImportError as error:
 print('PASS: core-only installed artifact imports Nanochat adapter without extras; missing submodule raises explicit ThirdPartyImportError:',error)
else:
 raise AssertionError('Expected missing external Nanochat submodule')
